API_KEY_ENV = "ANTHROPIC_API_KEY"
DEFAULT_MAX_TOKENS = 4096


class AnthropicAPI:
    def __init__(
        self,
        *,
        client: Any = None,
        timeout_s: int = CALL_TIMEOUT_S,
        max_tokens: int = DEFAULT_MAX_TOKENS,
    ) -> None:
        """`client` is anything with `.messages.create(...)`; tests inject a fake."""
        self._client = client
        self.timeout_s = timeout_s
        self.max_tokens = max_tokens

    def preflight(self) -> None:
        if self._client is None and not os.environ.get(API_KEY_ENV):
            raise LLMUnavailableError(
                f"{API_KEY_ENV} is not set; the anthropic_api backend needs an API key. "
                "Export it, or use --llm claude_cli (subscription) or --llm mock."
            )

    def _sdk(self) -> Any:
        if self._client is None:
            self.preflight()
            # No SDK retries: a failed call is one failed attempt for the agent loop,
            # as with claude_cli.
            self._client = anthropic.Anthropic(
                api_key=os.environ[API_KEY_ENV], max_retries=0, timeout=self.timeout_s
            )
        return self._client

    def complete(self, *, system: str, prompt: str, model: str) -> LLMResponse:
        try:
            client = self._sdk()
        except LLMUnavailableError as exc:
            raise LLMError(str(exc)) from exc
        with IN_FLIGHT:
            started = time.monotonic()
            try:
                message = client.messages.create(
                    model=model,
                    max_tokens=self.max_tokens,
                    system=system,
                    messages=[{"role": "user", "content": prompt}],
                    timeout=self.timeout_s,
                )
            except anthropic.APITimeoutError as exc:
                raise LLMTimeoutError(f"anthropic_api call timed out after {self.timeout_s} s") from exc
            except anthropic.APIError as exc:
                raise LLMError(f"anthropic_api call failed: {exc}") from exc
            wall_s = time.monotonic() - started
        return _parse(message, wall_s)


def _count(usage: Any, name: str) -> int:
    return int(getattr(usage, name, 0) or 0)


def _parse(message: Any, wall_s: float) -> LLMResponse:
    text = "".join(block.text for block in message.content if getattr(block, "type", None) == "text")
    if not text:
        raise LLMError(f"anthropic_api reply has no text (stop_reason={getattr(message, 'stop_reason', None)})")
    usage = message.usage
    return LLMResponse(
        text=text,
        usage=Usage(
            # Same mapping as claude_cli: cache writes are new input; cache reads
            # are reported apart and excluded from the budget (D5).
            tokens_in=_count(usage, "input_tokens") + _count(usage, "cache_creation_input_tokens"),
            tokens_out=_count(usage, "output_tokens"),
            cache_tokens=_count(usage, "cache_read_input_tokens"),
        ),
        latency_s=round(wall_s, 3),
    )
"""The LLMClient interface every backend implements, and the errors backends raise."""

from __future__ import annotations

import threading
from typing import Protocol

from pydantic import BaseModel


class Usage(BaseModel):
    """Tokens for one or more calls.

    `tokens_in` = uncached input + cache writes. `cache_tokens` = cache reads only,
    which the token budget excludes (D5)."""

    tokens_in: int = 0
    tokens_out: int = 0
    cache_tokens: int = 0

    def __add__(self, other: Usage) -> Usage:
        return Usage(
            tokens_in=self.tokens_in + other.tokens_in,
            tokens_out=self.tokens_out + other.tokens_out,
            cache_tokens=self.cache_tokens + other.cache_tokens,
        )


class LLMResponse(BaseModel):
    text: str
    usage: Usage = Usage()
    latency_s: float = 0.0


class LLMError(RuntimeError):
    """One LLM call failed. The agent loop counts it as a failed attempt."""


class LLMTimeoutError(LLMError):
    """One LLM call ran past its timeout."""


class LLMRateLimitError(LLMError):
    """The backend refused the call because of a rate limit or a subscription usage cap.

    Unlike other LLMErrors this is not an ordinary failed attempt: retrying soon will
    fail again. The agent loop, `ask` and the graph let it propagate out of
    `investigate()`, so the eval runner can stop cleanly and print the resume command."""


class LLMUnavailableError(RuntimeError):
    """The backend cannot run at all (CLI missing, not logged in). Raised before a run starts."""


class LLMClient(Protocol):
    def preflight(self) -> None:
        """Raise LLMUnavailableError if this backend cannot serve calls."""
        ...

    def complete(self, *, system: str, prompt: str, model: str) -> LLMResponse: ...


# Shared by every backend in the process (Q20): each call times out after 120 s,
# and at most 3 LLM calls are in flight at once, whichever backends serve them.
CALL_TIMEOUT_S = 120
MAX_IN_FLIGHT = 3
IN_FLIGHT = threading.BoundedSemaphore(MAX_IN_FLIGHT)
"""Build LLM clients by backend name, and route each role to the backend the models config names (Q20).

`RoleRouter` is itself an `LLMClient`. Today the graph passes one client to every
agent and names the role only through `model=models.model_for(role)`, so
`complete()` dispatches by that model string. A caller that knows the role can use
`client_for(role)` instead, which also allows one model on two backends.
"""

from __future__ import annotations

from collections.abc import Mapping

from incident_investigator.llm.anthropic_api import AnthropicAPI
from incident_investigator.llm.base import LLMClient, LLMError, LLMResponse
from incident_investigator.llm.claude_cli import ClaudeCLI
from incident_investigator.llm.mock import MockLLM
from incident_investigator.llm.openai_compat import OpenAICompat
from incident_investigator.models_config import BACKENDS, ModelsConfig, ModelsConfigError


def make_client(backend: str, models: ModelsConfig) -> LLMClient:
    """One client for `backend`. Raises ModelsConfigError for an unknown name."""
    if backend == "claude_cli":
        return ClaudeCLI()
    if backend == "anthropic_api":
        return AnthropicAPI()
    if backend == "openai_compat":
        return OpenAICompat(base_url=models.backends.openai_compat.base_url)
    if backend == "mock":
        return MockLLM()
    raise ModelsConfigError(f"unknown backend {backend!r}; choose one of: {', '.join(BACKENDS)}")


class RoleRouter:
    def __init__(
        self,
        models: ModelsConfig,
        *,
        clients: Mapping[str, LLMClient] | None = None,
        route_by_model: bool = True,
    ) -> None:
        """`clients` maps backend name to client (tests inject fakes); missing ones are built.

        With `route_by_model`, a model string assigned to two backends is a startup
        error, because `complete(model=...)` could not tell them apart."""
        self.models = models
        self._clients: dict[str, LLMClient] = {}
        self._role_backend = {role: models.backend_for(role) for role in models.role_names()}
        for backend in dict.fromkeys(self._role_backend.values()):
            given = (clients or {}).get(backend)
            self._clients[backend] = given if given is not None else make_client(backend, models)

        self._model_backend: dict[str, str] = {}
        if route_by_model:
            for role, backend in self._role_backend.items():
                model = models.model_for(role)
                other = self._model_backend.setdefault(model, backend)
                if other != backend:
                    raise ModelsConfigError(
                        f"model {model!r} is assigned to two backends ({other}, {backend}); "
                        "the graph routes LLM calls by model name, so give each backend distinct model names"
                    )

    def client_for(self, role: str) -> LLMClient:
        if role not in self._role_backend:
            raise KeyError(f"unknown role {role!r}")
        return self._clients[self._role_backend[role]]

    def preflight(self) -> None:
        for client in self._clients.values():
            client.preflight()

    def complete(self, *, system: str, prompt: str, model: str) -> LLMResponse:
        backend = self._model_backend.get(model)
        if backend is None:
            raise LLMError(f"model {model!r} is not assigned to any role in the models config")
        return self._clients[backend].complete(system=system, prompt=prompt, model=model)
