__all__ = [
    "CALL_TIMEOUT_S",
    "MAX_IN_FLIGHT",
    "ClaudeCLI",
    "LLMError",
    "LLMRateLimitError",
    "LLMTimeoutError",
    "LLMUnavailableError",
]

_PREFLIGHT_TIMEOUT_S = 30

# Shared by every backend in the process: at most 3 calls in flight (Q20).
_IN_FLIGHT = IN_FLIGHT

# Variables that tie a child `claude` to a parent Claude Code session. Auth
# variables such as CLAUDE_CODE_OAUTH_TOKEN are kept.
_PARENT_SESSION_VARS = {
    "CLAUDECODE",
    "CLAUDE_CODE_ENTRYPOINT",
    "CLAUDE_CODE_SESSION_ID",
    "CLAUDE_CODE_CHILD_SESSION",
    "CLAUDE_CODE_SESSION_ATTENDED",
    "CLAUDE_CODE_MESSAGING_SOCKET",
    "CLAUDE_CODE_MESSAGING_TOKEN",
    "CLAUDE_CODE_EXECPATH",
    "CLAUDE_PID",
    "CLAUDE_EFFORT",
}


# Markers of a rate limit or a subscription usage cap, matched case-insensitively and
# only on a failed call (an error result, a non-zero exit or no JSON), in the result
# text and stderr. Conservative on purpose: anything else stays an ordinary LLMError.
#   "rate limit" / "rate_limit" / "rate-limit"   API rate_limit_error, "Rate limit exceeded"
#   "usage limit"                                 "Claude AI usage limit reached|<epoch>"
#   "hit your limit", "<n>-hour limit",
#   "session limit", "weekly limit"               subscription window caps ("resets 3pm")
#   429                                           HTTP Too Many Requests ("API Error: 429 ...")
#   "overloaded", 529                             API overloaded_error: transient, also worth a pause
_RATE_LIMIT = re.compile(
    r"rate[ _-]?limit|usage limit|hit your limit|\b\d+-hour limit|session limit|weekly limit"
    r"|overloaded|\b(?:429|529)\b",
    re.IGNORECASE,
)


def _failed(message: str, *evidence: str) -> LLMError:
    """The error for a failed call: LLMRateLimitError when any text shows a rate limit or cap."""
    if any(_RATE_LIMIT.search(text) for text in evidence if text):
        return LLMRateLimitError(message)
    return LLMError(message)


def _isolated_workdir() -> Path:
    """A working directory outside any project, so no project CLAUDE.md or hooks load."""
    path = Path(tempfile.gettempdir()) / "incident-investigator-claude-cwd"
    path.mkdir(exist_ok=True)
    return path


def _child_env() -> dict[str, str]:
    return {k: v for k, v in os.environ.items() if k not in _PARENT_SESSION_VARS}


class ClaudeCLI:
    def __init__(self, *, executable: str = "claude", timeout_s: int = CALL_TIMEOUT_S) -> None:
        self.executable = executable
        self.timeout_s = timeout_s

    def command(self, *, system: str, model: str) -> list[str]:
        return [
            self.executable,
            "-p",
            "--output-format", "json",
            "--model", model,
            "--system-prompt", system,
            "--tools", "",
            "--setting-sources", "",
            "--strict-mcp-config",
            "--mcp-config", '{"mcpServers":{}}',
            "--no-session-persistence",
            "--disable-slash-commands",
        ]  # fmt: skip

    def preflight(self) -> None:
        if shutil.which(self.executable) is None:
            raise LLMUnavailableError(
                f"Claude CLI {self.executable!r} not found on PATH. "
                "Install Claude Code or use --llm mock."
            )
        try:
            done = subprocess.run(
                [self.executable, "auth", "status"],
                capture_output=True,
                text=True,
                timeout=_PREFLIGHT_TIMEOUT_S,
                cwd=_isolated_workdir(),
                env=_child_env(),
            )
            status = json.loads(done.stdout)
        except (subprocess.TimeoutExpired, json.JSONDecodeError, OSError) as exc:
            raise LLMUnavailableError(f"could not read `claude auth status`: {exc}") from exc
        if not (isinstance(status, dict) and status.get("loggedIn")):
            raise LLMUnavailableError("Claude CLI is not logged in. Run `claude login` first.")

    def complete(self, *, system: str, prompt: str, model: str) -> LLMResponse:
        args = self.command(system=system, model=model)

