cd /Users/<user>/Documents/Learning/Orange && ls -la runs/api/52054ab4df6240d0ad7958e56f4f5cb1.json && python3 - <<'EOF'
import json
d = json.load(open("runs/api/52054ab4df6240d0ad7958e56f4f5cb1.json"))
print({k: d[k] for k in ["status","mode","incident_id","created_at","finished_at"]}, "error:", str(d["error"])[:300])
r = d.get("report")
if r:
    print(r["outcome"], r["terminated_by"], r["metrics"])
    for h in r["ranked_hypotheses"]:
        print("H", h["id"], h["service"], h["category"], h["proposed_confidence"], "->", h["final_confidence"], "sup", h["supporting_ids"], "con", h["contradicting_ids"])
        print("   ", h["summary"][:400])
    print("gaps:", r["gaps"])
    for a in r["rule_adjustments"]: print("adj", a["rule"], a["subject"], a.get("ids"), a.get("confidence_before"), a.get("confidence_after"))
    print("failures:", [(f["task_id"], f["reason"][:300], f["attempts"]) for f in r["failures"]])
    for a in r["recommended_actions"]: print("ACT", a["hypothesis_id"], a["action"][:150])
    print("uncited->assumptions:", sum("cites no evidence IDs" in a["basis"] for a in r["assumptions"]), "of", len(r["assumptions"]), "facts", len(r["facts"]))
    b = d["blackboard"]
    print("closed_gaps", b.get("closed_gaps"), "critic_loops", b["critic_loops"])
    for t in b["trace"]: print(" trace", t["task_id"], t["agent"], t["status"], "tools", t["tool_calls"], "llm", t["llm_calls"])
    for t in b["tasks"]: print(" task", t["id"], t["status"], t["goal"][:110])
    for c in b["critic_reviews"]: print(" critic", c["loop"], len(c.get("follow_ups") or []), c["critique"][:300].replace("\n"," "))
    print("evidence:", sorted(e["id"] for e in b["evidence"]))
EOF

